<script setup lang="ts">
import {ref,nextTick,onMounted,onUnmounted,watch} from 'vue';
const props=defineProps<{label:string;disabled?:boolean;options:{value:string;label:string;disabled?:boolean}[]}>();
const emit=defineEmits<{select:[value:string]}>();
const open=ref(false),root=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null);
const placement=ref({});watch(open,async value=>{if(!value)return;await nextTick();const rect=trigger.value?.getBoundingClientRect();if(!rect)return;const height=props.options.length*40+12;placement.value={position:'fixed',right:`${Math.max(12,innerWidth-rect.right)}px`,top:`${Math.max(12,Math.min(rect.bottom+4,innerHeight-height-12))}px`,maxHeight:`${innerHeight-24}px`,overflowY:'auto'};});
function close(restore=false){open.value=false;if(restore)void nextTick(()=>trigger.value?.focus());}
async function key(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);}else if(event.key==='Tab')close();else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();open.value=true;await nextTick();const buttons=[...root.value!.querySelectorAll<HTMLButtonElement>('[role=menuitem]:not(:disabled)')];const i=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(i+(event.key==='ArrowUp'?-1:1)+buttons.length)%buttons.length]?.focus();}}
function outside(event:Event){if(!root.value?.contains(event.target as Node))close();}
function select(value:string){close(true);emit('select',value);}
onMounted(()=>document.addEventListener('click',outside));onUnmounted(()=>document.removeEventListener('click',outside));
</script>
<template><div ref="root" class="monitor-menu" @keydown="key" @focusout="!root?.contains($event.relatedTarget as Node)&&close()"><button ref="trigger" type="button" :aria-label="label" aria-haspopup="menu" :aria-expanded="open" :disabled="disabled" @click="open=!open"><svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg></button><div v-if="open" role="menu" :aria-label="label" class="menu" :style="placement"><button v-for="option in options" :key="option.value" type="button" role="menuitem" :disabled="option.disabled" @click="select(option.value)">{{option.label}}</button></div></div></template>
<style scoped>.monitor-menu{position:relative;flex:none}.monitor-menu>button{display:grid;place-items:center;width:36px;height:36px;padding:0;background:transparent;border:0;color:var(--text-lo);cursor:pointer;border-radius:6px}.menu{position:absolute;right:0;top:100%;min-width:170px;padding:5px;display:grid;z-index:40;background:var(--bg-raised);border:1px solid var(--accent-dim);border-radius:8px;box-shadow:0 8px 24px #0006}.menu button{font:inherit;font-size:13px;min-height:38px;white-space:nowrap;text-align:left;padding:6px 10px;border:0;background:transparent;color:var(--text-hi);cursor:pointer}.menu button:hover{background:var(--bg-panel)}button:disabled{opacity:.45;cursor:default}button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}</style>
